from lib import *
S = SS('k54')
F1 = [['容器 exit 1', 'kubelet 重启容器'], ['/v/log 和 seen', '还在'], ['删除 Pod', '目录 2.3 秒内消失'], ['同名新 Pod', '空目录']]
F2 = [['默认(磁盘)', 'ext4,df 是整块盘'], ['medium: Memory', 'tmpfs,大小=节点内存'], ['写 50MiB', 'shmem 增加 50MiB'], ['磁盘卷', '只是页缓存 file']]
F3 = [['limit 64Mi + Memory 卷', ''], ['写 100MiB', '7 秒 OOMKilled'], ['重启', 'init 被 OOM 杀,RunContainerError'], ['CrashLoopBackOff', '循环']]
F4 = [['Memory + sizeLimit 20Mi', 'tmpfs 大小 20Mi'], ['写 30MiB', 'No space left on device'], ['磁盘 + sizeLimit 20Mi', 'df 仍是整块盘'], ['写 30MiB 之后', 'kubelet 驱逐 Pod']]
PANELS = [('f', 'flow', 'emptyDir 的行为'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Pod life 的容器第一次运行时往 /v/log 写一行、建 /v/seen,4 秒后 exit 1,kubelet 重启容器(restartCount=1);重启后 /v 里的 log、seen 都还在,/v/log 有两行:第一次运行、容器重启后又运行。节点上这个目录是 /var/lib/kubelet/pods/<uid>/volumes/kubernetes.io~empty-dir/v。删除 Pod 之后,2.3 秒内这个目录就没了;同名 Pod 再建出来,/v/log 里只有新 Pod 写的一行——是新目录。", f=fl(F1, cur=[0, 1], mark=[2], done=[3]), t=tl(S(1), mark=lidx(S(1), 'restartCount=1', '消失了'), done=lidx(S(1), '新 Pod 写入')), kv=KV([['跟 Pod 走', '创建 Pod 时建目录,删 Pod 时删'], ['容器重启', '不影响,文件跨容器保留'], ['同名新 Pod', '拿到的是新的空目录']], ['跟 Pod 走'])),
    step("默认的 emptyDir 是节点磁盘上的目录(/proc/mounts 里是 ext4,df 看到整块盘 474 GB);medium: Memory 是 tmpfs,没写 sizeLimit 时大小是 8124516k,正好等于节点 MemTotal。各写 50 MiB:两个卷的容器 memory.current 都增加约 50 MiB;区别在 memory.stat——Memory 卷的 shmem=51200 KiB,磁盘卷的 shmem=0、只是 file(页缓存)。", f=fl(F2, cur=[1, 2], mark=[3]), t=tl(S(2), mark=lidx(S(2), 'tmpfs', 'shmem(tmpfs 页)=51200'), done=lidx(S(2), 'ext4', 'shmem(tmpfs 页)=0')), b=bars([['磁盘卷:shmem', 0, '0 KiB'], ['Memory 卷:shmem', 51200, '51200 KiB']], 51200, done=[1]), kv=KV([['磁盘卷', '页缓存算在 cgroup 里但可回收'], ['Memory 卷', 'tmpfs 页是 shmem,不能直接丢掉'], ['默认大小', '没有 sizeLimit 就是整个节点内存']], ['Memory 卷'])),
    step("容器 memory limit 64Mi,往 Memory 卷写 100 MiB:容器状态依次是 running → 7.0 秒 terminated:OOMKilled(restartCount 0)→ waiting:RunContainerError(restartCount 1)→ CrashLoopBackOff → RunContainerError(restartCount 2)。重启的容器 init 阶段就被 OOM 杀,message 是 container init was OOM-killed (memory limit too low?);这时 Pod 的 memory.current 还有 62 MiB——tmpfs 里的数据没有随容器消失。", f=fl(F3, cur=[1, 2], mark=[0], done=[]), t=tl(S(3), mark=lidx(S(3), 'OOMKilled', 'RunContainerError'), done=lidx(S(3), 'memory.current=62 MiB')), kv=KV([['写 Memory 卷', '内存算在写入者的 cgroup 里'], ['容器被杀', 'tmpfs 数据还在,占着 Pod 的内存'], ['重启', '一开始就 OOM,进入 CrashLoopBackOff']], ['写 Memory 卷'])),
    step("sizeLimit: 20Mi:Memory 卷的 tmpfs 大小就是 20480 KiB,写 30 MiB 当场报 No space left on device,只写进去 20 MiB,Pod 仍是 Running。磁盘卷的 sizeLimit 不是文件系统配额:df 仍是整块盘,写 30 MiB 毫无阻碍;之后 kubelet 的周期检查发现超限,24 秒后 Pod 变成 Failed、reason=Evicted,message 是 Usage of EmptyDir volume \"v\" exceeds the limit \"20Mi\"。", f=fl(F4, cur=[1, 3], mark=[0, 2]), t=tl(S(4), mark=lidx(S(4), 'No space left', 'phase=Failed'), done=lidx(S(4), 'Evicted:')), kv=KV([['Memory 卷', 'sizeLimit 变成 tmpfs 大小,立刻 ENOSPC'], ['磁盘卷', 'sizeLimit 只是驱逐阈值,不限制写入'], ['驱逐时机', '要等 kubelet 下一轮检查,不是立刻']], ['磁盘卷'])),
]
A = mkartk('k54', 54, 'Kubernetes,emptyDir,tmpfs,sizeLimit,存储,真实验证,动画演示',
    '在 kind 集群里实测 emptyDir:容器重启后文件还在、删除 Pod 后节点上的目录 2.3 秒内消失;medium: Memory 是 tmpfs,默认大小等于节点内存,写 50 MiB 在 memory.stat 里变成 shmem;tmpfs 的页算在容器内存里,limit 64Mi 写 100 MiB 会 OOMKilled 并陷入 CrashLoopBackOff;sizeLimit 对 Memory 卷是立刻 ENOSPC,对磁盘卷则是 kubelet 周期检查后的驱逐。',
    'emptyDir 到底存在哪?容器重启后文件还在吗?medium: Memory 占的是谁的内存?sizeLimit 是配额吗?这篇在真集群里读节点上的目录、/proc/mounts 和 cgroup 的 memory.stat,把这些问题都实际验证一遍。',
    [('2.3 秒', '删除 Pod 后节点上 emptyDir 目录消失所用时间'), ('51200 KiB', 'Memory 卷写入 50 MiB 后 cgroup 的 shmem 增量(磁盘卷是 0)'), ('24 秒', '磁盘卷写超 sizeLimit 后 Pod 被驱逐所用时间(多次运行在 24~45 秒之间)')],
    [('生命周期跟着 Pod', '<p>节点上 emptyDir 的目录在 <code>/var/lib/kubelet/pods/&lt;uid&gt;/volumes/kubernetes.io~empty-dir/&lt;卷名&gt;</code>。容器自己 <code>exit 1</code> 被 kubelet 重启后,<code>/v</code> 里的 <code>log</code> 和 <code>seen</code> 都还在,日志里能看到“第一次运行”和“容器重启后又运行”两行——emptyDir 的文件跨容器重启保留。</p><p>删除 Pod 后 2.3 秒内节点上的目录消失;同名 Pod 重建后拿到的是一个空目录。它的生命周期跟 Pod(uid)绑定,不跟容器,也不跟名字。</p>'),
     ('medium: Memory 就是 tmpfs', '<p>默认的 emptyDir 是节点磁盘上的目录(<code>/proc/mounts</code> 里是 ext4,<code>df</code> 看到的是整块盘);<code>medium: Memory</code> 是 <code>tmpfs</code>,没写 <code>sizeLimit</code> 时大小是 8124516k,正好等于节点的 MemTotal。</p><p>各写 50 MiB:两个容器的 <code>memory.current</code> 都涨了约 50 MiB,区别在 <code>memory.stat</code>:Memory 卷的 <code>shmem</code> 是 51200 KiB,磁盘卷的 <code>shmem</code> 是 0,只是可回收的页缓存(<code>file</code>)。tmpfs 的页是共享内存,没有 swap 时不能直接丢掉,所以它是真正占着的内存。</p>'),
     ('写 Memory 卷也会 OOM', '<p>容器 memory limit 64Mi,往 Memory 卷写 100 MiB:约 7 秒时容器 <code>OOMKilled</code>;重启后新容器在 init 阶段就被 OOM 杀,<code>RunContainerError</code>,message 是 <code>container init was OOM-killed (memory limit too low?)</code>,接着 <code>CrashLoopBackOff</code>。此时 Pod 级 <code>memory.current</code> 还有 62 MiB,tmpfs 里的数据没有随旧容器一起消失,新容器一启动就背着这些内存。</p><p>所以 Memory 卷要和容器的 memory limit 一起算,而且最好设 <code>sizeLimit</code>。</p>'),
     ('sizeLimit 的两种含义', '<p>Memory 卷设 <code>sizeLimit: 20Mi</code>,tmpfs 的大小就是 20480 KiB,写 30 MiB 立刻 <code>No space left on device</code>,Pod 仍是 Running。磁盘卷的 <code>sizeLimit</code> 不是文件系统配额:<code>df</code> 仍是整块盘,写 30 MiB 毫无阻碍,要等 kubelet 下一轮检查才发现超限,24 秒后 Pod 变成 <code>Failed</code>、reason <code>Evicted</code>,message 是 <code>Usage of EmptyDir volume "v" exceeds the limit "20Mi"</code>。</p><p>这个检查周期不固定——多次运行里是 24~45 秒——不要依赖它做实时限制。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(Kubernetes v1.37.0),节点是 cgroup v2;节点上的目录用 docker exec 进节点读;memory.current / memory.stat 读容器的 cgroup;“2.3 秒”“24 秒”是轮询得到的单次值,驱逐时间多次运行在 24~45 秒之间;第三节的容器状态序列用 0.15 秒间隔轮询得到;每种情形各一次',
     '没有验证:SizeMemoryBackedVolumes 与 Pod 的 memory limit 的关系(tmpfs 默认大小取节点内存还是 Pod limit,依版本与特性开关而定);hugepages 介质;emptyDir 里的 fsGroup 与权限;多个容器共享同一个 emptyDir;kubelet 检查 emptyDir 用量的周期(是否由某个参数控制);emptyDir 用量计入 ephemeral-storage 并触发节点压力驱逐(见后面的 ephemeral-storage 一篇)'],
    'emptyDir', PANELS)
